shipped_spans.nodes_for:
fn nodes_for(j:usize)->[M31;9] {
    core::array::from_fn(|depth|{
        let p=domain::fibre_point::<M31>(FibreIndex::new((j>>depth)<<depth).unwrap());
        let mut n=tcheb(p.x);
        for _ in 0..depth {n=tcheb(n);}
        n
    })
}
